rkbench',NULL,'SKIPPED',0,NULL,NULL,'2026-10-20 09:00:00.000'),(9100000000000110009,204,'WARNING','年度目标推进提醒','「校内实训工位规模」2026 年当前审核通过值为 3350 个，年度目标为 3400 个，请跟进改造项目验收与资产登记。',NULL,NULL,'/plans',NULL,'SKIPPED',0,NULL,NULL,'2026-10-22 09:00:00.000');
